    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    s = data[1]

    # Find the longest prefix that is lexicographically greater than its suffix
    for i in range(n-1):
        if s[i] > s[i+1]:
            # Reverse the suffix starting from i+1
            return "YES\n{} {}".format(i+1, n)

    # If no such prefix is found, check for the longest increasing prefix
    max_length = 0
    start = 0

    for i in range(1, n):
        if s[i] <= s[i-1]:
            if i - start > max_length:
                max_length = i - start
                end = i - 1
            start = i

    if n - start > max_length:
        end = n - 1

    if end == n - 1:
        return "NO"
    else:
        return "YES\n{} {}".format(end + 1, n)

